import ast, sys, collections
src = open(sys.argv[1], encoding="utf-8").read()
tree = ast.parse(src)
defs = {}   # name -> (start, end)
for n in tree.body:
    names = []
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)):
        names = [n.name]
    elif isinstance(n, ast.Assign):
        for t in n.targets:
            for x in ast.walk(t):
                if isinstance(x, ast.Name):
                    names.append(x.id)
    elif isinstance(n, ast.AnnAssign) and isinstance(n.target, ast.Name):
        names = [n.target.id]
    start = min([n.lineno] + [d.lineno for d in getattr(n, "decorator_list", [])])
    for nm in names:
        defs[nm] = (start, n.end_lineno)
deps = collections.defaultdict(set)
for n in tree.body:
    owners = []
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)):
        owners = [n.name]
    elif isinstance(n, (ast.Assign, ast.AnnAssign)):
        ts = n.targets if isinstance(n, ast.Assign) else [n.target]
        owners = [x.id for t in ts for x in ast.walk(t) if isinstance(x, ast.Name)]
    used = {x.id for x in ast.walk(n) if isinstance(x, ast.Name)}
    for o in owners:
        deps[o] |= {u for u in used if u in defs and u != o}
# SCC (Tarjan)
idx = {}; low = {}; st = []; on = set(); out = []; c = [0]
sys.setrecursionlimit(10000)
def sc(v):
    idx[v] = low[v] = c[0]; c[0] += 1; st.append(v); on.add(v)
    for w in deps[v]:
        if w not in idx:
            sc(w); low[v] = min(low[v], low[w])
        elif w in on:
            low[v] = min(low[v], idx[w])
    if low[v] == idx[v]:
        comp = []
        while True:
            w = st.pop(); on.discard(w); comp.append(w)
            if w == v: break
        out.append(comp)
for v in defs:
    if v not in idx: sc(v)
for comp in out:
    if len(comp) > 1:
        print(sorted(comp, key=lambda x: defs[x][0]), [defs[x][0] for x in comp][:0])

