import ast, os, re, sys, collections

SRC = r"C:\Users\Георгий\AppData\Local\Temp\dg_orig.py"
OUT = sys.argv[1]  # .claude/hooks
PKG = os.path.join(OUT, "dguard")
os.makedirs(PKG, exist_ok=True)

text = open(SRC, encoding="utf-8").read()
lines = text.split("\n")
tree = ast.parse(text)

STATE = {"LOCAL_ROOTS", "WRITE_HOME_ROOTS", "PROJECT_DIR", "PROTECTED", "PROTECTED_ERROR", "REMOTE_ROOTS", "STAGE", "CLOSED_RE"}
CMD_SCAN = {"python_consts", "const_str", "python_scan", "find_scan", "ssh_scan", "record_var", "scan_one", "generic_scan",
            "scan_cmds", "scan_text"}
OVERRIDE = {n: "cmd_scan" for n in CMD_SCAN}
OVERRIDE.update({"del_targets": "writes", "rsync_scan": "writes", "shell_code": "words", "ps_code": "words"})
RANGES = [(63, 155, "config"), (156, 235, "messages"), (236, 421, "paths"), (422, 761, "lexer"), (762, 927, "words"),
          (928, 1044, "cmd_scan"), (1045, 1201, "publish"), (1202, 1318, "writes"), (1319, 1552, "git_scan"),
          (1553, 1840, "writes"), (1841, 2050, "cmd_scan"), (2051, 2101, "legacy"), (2102, 2418, "policy"),
          (2419, 2517, "checks"), (2518, 2627, "ceo_signal")]
DOCS = {
    "config": "Настройки стража: корни своей папки, защищённые пути и удалённые машины из `.claude/rpv.json`; `configure` их ставит.",
    "messages": "Тексты отказов и классы причин (`Over`, `Forbid`, `Publish`, `BranchDelete`).",
    "paths": "Пути: что считается своей папкой, временным каталогом и можно ли писать в цель.",
    "lexer": "Лексер shell-строки: разбор на простые команды (кавычки, heredoc, `$(…)`, перенаправления).",
    "words": "Слова простой команды: переменные, обёртки (sudo/env/xargs/…), хост и путь, код `bash -c` / `powershell -Command`.",
    "cmd_scan": "Разбор простой команды рекурсивно: удаление, Python-код, `find`, `ssh`, обёртки; вход — `scan_text`.",
    "publish": "Публикации (выпуск, слияние, `gh api`, curl/wget/Invoke-WebRequest с записью), необратимые для запуска роли.",
    "writes": "Удаление и запись в файл: `rm`, `cp`/`mv`, `tee`, PowerShell-командлеты, `truncate`, `dd`, `rsync`.",
    "git_scan": "Команды git: необратимые (`reset --hard`, `clean`, `push --force`), удаление веток, публикация пушем.",
    "legacy": "Прежний регэксп как страховка, когда команду не удалось разобрать (незакрытая кавычка).",
    "policy": "Личность запуска, согласия на публикацию, защищённые пути, настройки, уставы, слово владельца.",
    "checks": "Проверка команды и файла целиком: `check` (Bash/PowerShell), `check_file` (Write/Edit/…).",
    "ceo_signal": "Сигналы CEO (`ceo-inbox.md`, `ceo-wake.log`) пишет только диспетчер.",
}


def module_of(name, start):
    if name.startswith("REASON_") or name == "UNKNOWN_TARGET":
        return "messages"
    if name in OVERRIDE:
        return OVERRIDE[name]
    for a, b, m in RANGES:
        if a <= start <= b:
            return m
    return None


nodes = []   # (start, end, names, node)
prev_end = 0
for n in tree.body:
    start = min([n.lineno] + [d.lineno for d in getattr(n, "decorator_list", [])])
    seg_start = prev_end + 1
    names = []
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)):
        names = [n.name]
    elif isinstance(n, ast.Assign):
        names = [x.id for t in n.targets for x in ast.walk(t) if isinstance(x, ast.Name)]
    elif isinstance(n, ast.AnnAssign):
        names = [n.target.id]
    nodes.append((seg_start, n.end_lineno, start, names, n))
    prev_end = n.end_lineno

assign = {}      # name -> module
by_module = collections.defaultdict(list)
for seg_start, end, start, names, n in nodes:
    if not names:
        continue
    mod = module_of(names[0], start)
    if mod is None:
        continue
    for nm in names:
        assign[nm] = mod
    by_module[mod].append((seg_start, end, names, n))

STD = ["ast", "base64", "fnmatch", "json", "os", "posixpath", "re", "textwrap"]
graph = collections.defaultdict(set)
out_src = {}
for mod, items in by_module.items():
    body_lines = []
    uses = set()
    std_used = set()
    for seg_start, end, names, n in items:
        seg = lines[seg_start - 1:end]
        # переписать чтение состояния на config.<имя> (кроме самого config)
        edits = []
        for x in ast.walk(n):
            if isinstance(x, ast.Name):
                if x.id in assign and assign[x.id] != mod:
                    uses.add(x.id)
                if x.id in STD:
                    std_used.add(x.id)
                if mod != "config" and x.id in STATE:
                    edits.append((x.lineno, x.col_offset, len(x.id)))
        for ln, col, ln_len in sorted(edits, reverse=True):
            idx = ln - seg_start
            line = seg[idx]
            b = line.encode("utf-8")
            b = b[:col] + b"config." + b[col:]
            seg[idx] = b.decode("utf-8")
        body_lines.extend(seg)
    # global-объявления в configure остаются (config)
    imports = []
    for s in STD:
        if s in std_used:
            imports.append(f"import {s}")
    by_src = collections.defaultdict(list)
    need_config = False
    for u in sorted(uses):
        if u in STATE:
            need_config = True
            continue
        by_src[assign[u]].append(u)
        graph[mod].add(assign[u])
    if need_config:
        graph[mod].add("config")
    # state names used without Name nodes of other module (config is source): detect via edits
    if mod != "config" and any(re.search(r"\bconfig\.", l) for l in body_lines):
        need_config = True
        graph[mod].add("config")
    head = f'"""{DOCS[mod]}"""\n' + "\n".join(imports)
    froms = []
    if need_config:
        froms.append("from dguard import config")
    for src in sorted(by_src):
        names = by_src[src]
        froms.append(f"from dguard.{src} import " + ", ".join(sorted(names, key=lambda s: s.lower())))
    parts = [head]
    if imports:
        parts[-1] += ""
    block = "\n".join(imports + froms)
    src_text = f'"""{DOCS[mod]}"""\n' + (block + "\n" if block else "") + "\n\n" + "\n".join(body_lines).lstrip("\n") + "\n"
    out_src[mod] = src_text

# циклы между модулями
def cyc():
    seen = {}
    def dfs(v, path):
        seen[v] = 1
        for w in graph[v]:
            if seen.get(w) == 1:
                print("ЦИКЛ:", " -> ".join(path + [v, w]))
            elif w not in seen:
                dfs(w, path + [v])
        seen[v] = 2
    for v in list(graph):
        if v not in seen:
            dfs(v, [])
cyc()

for mod, s in out_src.items():
    open(os.path.join(PKG, mod + ".py"), "w", encoding="utf-8", newline="\n").write(s)
open(os.path.join(PKG, "__init__.py"), "w", encoding="utf-8", newline="\n").write(
    '"""Модули стража удаления (`../delete_guard.py` — вход и реэкспорт)."""\n')

# delete_guard.py: докстринг + остаток (check_tool, journal_guard, main)
head_doc = "\n".join(lines[:52])
rest_nodes = [(s, e, n) for (s, e, st, names, n) in nodes if st >= 2628 or (isinstance(n, ast.If))]
rest_lines = []
for s, e, n in rest_nodes:
    rest_lines.extend(lines[s - 1:e])
open(os.path.join(OUT, "_rest.txt"), "w", encoding="utf-8").write("\n".join(rest_lines))
for mod in sorted(by_module):
    print(mod, len(out_src[mod].split("\n")))
print("unassigned:", [(names, st) for (s, e, st, names, n) in nodes if names and module_of(names[0], st) is None])

