    except Exception as e:
        reason = _deny(trace, "crash", REASON_CRASH.format(e=f"{type(e).__name__}: {e}"[:200]))
    if trace and project:
        journal_guard(project, data.get("tool_name"), trace, reason)
    return deny(reason) if reason else 0


